{"target": {"id": "SpankChain.sol:function:13743:706", "kind": "function", "contract": "LedgerChannel", "signature": "LCOpenTimeout(bytes32)", "visibility": "public", "source": "function LCOpenTimeout(bytes32 _lcID) public {

require(msg.sender == Channels[_lcID].partyAddresses[0] && Channels[_lcID].isOpen == false);

require(now > Channels[_lcID].LCopenTimeout);

if(Channels[_lcID].initialDeposit[0] != 0) {
Channels[_lcID].partyAddresses[0].transfer(Channels[_lcID].ethBalances[0]);

}

if(Channels[_lcID].initialDeposit[1] != 0) {

require(Channels[_lcID].token.transfer(Channels[_lcID].partyAddresses[0], Channels[_lcID].erc20Balances[0]),"CreateChannel: token transfer failure");

}

emit DidLCClose(_lcID, 0, Channels[_lcID].ethBalances[0], Channels[_lcID].erc20Balances[0], 0, 0);

// only safe to delete since no action was taken on this channel

delete Channels[_lcID];

}"}, "available_context": [{"id": "SpankChain.sol:state_variable:12092:43", "kind": "state_variable", "name": "LedgerChannel.Channels", "reasons": ["state variable declaration: Channels"]}, {"id": "SpankChain.sol:function:12137:1604", "kind": "function", "name": "createChannel(bytes32,address,uint256,address,uint256[2])", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:14450:816", "kind": "function", "name": "joinChannel(bytes32,uint256[2])", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:15346:1103", "kind": "function", "name": "deposit(bytes32,address,uint256,bool)", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:16577:1756", "kind": "function", "name": "consensusCloseChannel(bytes32,uint256,uint256[4],string,string)", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:18358:1632", "kind": "function", "name": "updateLCstate(bytes32,uint256[6],bytes32,string,string)", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:24198:1553", "kind": "function", "name": "closeVirtualChannel(bytes32,bytes32)", "reasons": ["direct writer of state variable: Channels"]}, {"id": "SpankChain.sol:function:25844:2194", "kind": "function", "name": "byzantineCloseChannel(bytes32)", "reasons": ["direct writer of state variable: Channels"]}], "context_complete": false, "task": "verify_static_analysis_finding", "finding": {"id": "da49c1a96621ac0ec579d1887de3a8ce6ffd1be3d610c7819b78645f05e0e19f", "tool": "slither", "detector": "reentrancy-eth", "impact": "High", "confidence": "Medium", "description": "Reentrancy in LedgerChannel.LCOpenTimeout(bytes32) (examples/defihacklabs/SpankChain.sol#692-715):
